(function(global){
  "use strict";
  var dbName="FuelLedger";
  var storeName="app_state";
  var dbPromise=null;
  function clone(value){
    if (typeof structuredClone === "function") return structuredClone(value);
    return value == null ? value : JSON.parse(JSON.stringify(value));
  }
  function openDb(){
    if (!global.indexedDB) return Promise.resolve(null);
    if (dbPromise) return dbPromise;
    dbPromise = new Promise(function(resolve,reject){
      var request = global.indexedDB.open(dbName,1);
      request.onupgradeneeded = function(){
        var db = request.result;
        if (!db.objectStoreNames.contains(storeName)) db.createObjectStore(storeName);
      };
      request.onsuccess = function(){ resolve(request.result); };
      request.onerror = function(){ reject(request.error); };
    });
    return dbPromise;
  }
  function withStore(mode, callback){
    return openDb().then(function(db){
      if (!db) throw new Error("IndexedDB is unavailable");
      return new Promise(function(resolve,reject){
        var tx = db.transaction(storeName, mode);
        var store = tx.objectStore(storeName);
        var request;
        try { request = callback(store); } catch (error) { reject(error); return; }
        request.onsuccess = function(){ resolve(request.result); };
        request.onerror = function(){ reject(request.error); };
      });
    });
  }
  global.localforage = {
    config: function(options){
      if (options && options.name) dbName = String(options.name);
      if (options && options.storeName) storeName = String(options.storeName);
      dbPromise = null;
      return true;
    },
    getItem: function(key){
      return withStore("readonly", function(store){ return store.get(String(key)); }).then(function(value){
        return value === undefined ? null : clone(value);
      });
    },
    setItem: function(key, value){
      var saved = clone(value);
      return withStore("readwrite", function(store){ return store.put(saved, String(key)); }).then(function(){ return saved; });
    },
    removeItem: function(key){
      return withStore("readwrite", function(store){ return store.delete(String(key)); });
    }
  };
})(window);
